package aoc2022;class G{String s(boolean p,String x){int[]s=new int[x.length()],q=s.clone();int n=1,d=0,r=0;for(String l:x.split("\n")){char c=l.charAt(0);if(c<37){if(l.charAt(2)<100){c=l.charAt(5);if(c<48)d=c<47?d-1:0;else q[++d]=n++;}}else if(c<58){int v=$.i(l.split(" ")[0]);for(int i=0;i<=d;)s[q[i++]]+=v;}}int m=s[0]-40000000;for(int v:s)if(p){if(v<=100000)r+=v;}else if(v>=m&(r<1|v<r))r=v;return""+r;}}
